func (t *GetSlotDeclDeclaration) CompareTo(o any) int {
	ao := o.(Declaration)
	if ao == Declaration(t) {
		return 0
	}
	if t.Hash() != ao.Hash() {
		if t.Hash() < ao.Hash() {
			return -1
		}
		return 1
	}
	if c := strings.Compare(t.SymbolName(), ao.SymbolName()); c != 0 {
		return c
	}
	tco := ao.(*GetSlotDeclDeclaration)
	if c := t.AstName.CompareTo(tco.AstName); c != 0 {
		return c
	}
	if c := t.SlotName.CompareTo(tco.SlotName); c != 0 {
		return c
	}
	if c := t.Variable.CompareTo(tco.Variable); c != 0 {
		return c
	}
	if c := t.Expr.CompareTo(tco.Expr); c != 0 {
		return c
	}
	if c := t.OrgTrack.CompareTo(tco.OrgTrack); c != 0 {
		return c
	}
	panic(&aterm.GomError{Msg: "Unable to compare"})
}

func (t *GetSlotDeclDeclaration) CompareToLPO(o any) int {
	ao := o.(Declaration)
	if ao == Declaration(t) {
		return 0
	}
	if c := strings.Compare(t.SymbolName(), ao.SymbolName()); c != 0 {
		return c
	}
	tco := ao.(*GetSlotDeclDeclaration)
	if c := t.AstName.CompareToLPO(tco.AstName); c != 0 {
		return c
	}
	if c := t.SlotName.CompareToLPO(tco.SlotName); c != 0 {
		return c
	}
	if c := t.Variable.CompareToLPO(tco.Variable); c != 0 {
		return c
	}
	if c := t.Expr.CompareToLPO(tco.Expr); c != 0 {
		return c
	}
	if c := t.OrgTrack.CompareToLPO(tco.OrgTrack); c != 0 {
		return c
	}
	panic(&aterm.GomError{Msg: "Unable to compare"})
}

// ToATerm is the ATerm of the term: an application of GetSlotDecl.
func (t *GetSlotDeclDeclaration) ToATerm() aterm.ATerm {
	f := aterm.GetInstance()
	return f.MakeAppl(f.MakeAFun("GetSlotDecl", 5, false), t.AstName.ToATerm(), t.SlotName.ToATerm(), t.Variable.ToATerm(), t.Expr.ToATerm(), t.OrgTrack.ToATerm())
}

// fromTermGetSlotDeclDeclaration is Java Gom's GetSlotDecl.fromTerm: an unquoted application of
// GetSlotDecl whose arguments are convertible (as in Java, the arity is not
// checked: a missing argument is an index out of range).
func fromTermGetSlotDeclDeclaration(trm aterm.ATerm, conv aterm.ATermConverter) (Declaration, bool) {
	trm = conv.Convert(trm)
	if appl, ok := trm.(*aterm.ATermAppl); ok && appl.GetName() == "GetSlotDecl" && !appl.GetAFun().IsQuoted() {
		return MakeGetSlotDecl(TomNameFromTermConv(appl.GetArgument(0), conv), TomNameFromTermConv(appl.GetArgument(1), conv), BQTermFromTermConv(appl.GetArgument(2), conv), ExpressionFromTermConv(appl.GetArgument(3), conv), OptionFromTermConv(appl.GetArgument(4), conv)), true
	}
	return nil, false
}

