func (t *EqualTermDeclDeclaration) CompareTo(o any) int {
	ao := o.(Declaration)
	if ao == Declaration(t) {
		return 0
	}
	if t.Hash() != ao.Hash() {
		if t.Hash() < ao.Hash() {
			return -1
		}
		return 1
	}
	if c := strings.Compare(t.SymbolName(), ao.SymbolName()); c != 0 {
		return c
	}
	tco := ao.(*EqualTermDeclDeclaration)
	if c := t.TermArg1.CompareTo(tco.TermArg1); c != 0 {
		return c
	}
	if c := t.TermArg2.CompareTo(tco.TermArg2); c != 0 {
		return c
	}
	if c := t.Expr.CompareTo(tco.Expr); c != 0 {
		return c
	}
	if c := t.OrgTrack.CompareTo(tco.OrgTrack); c != 0 {
		return c
	}
	panic(&aterm.GomError{Msg: "Unable to compare"})
}

