func (t *IsSortDeclDeclaration) CompareTo(o any) int {
	ao := o.(Declaration)
	if ao == Declaration(t) {
		return 0
	}
	if t.Hash() != ao.Hash() {
		if t.Hash() < ao.Hash() {
			return -1
		}
		return 1
	}
	if c := strings.Compare(t.SymbolName(), ao.SymbolName()); c != 0 {
		return c
	}
	tco := ao.(*IsSortDeclDeclaration)
	if c := t.TermArg.CompareTo(tco.TermArg); c != 0 {
		return c
	}
	if c := t.Expr.CompareTo(tco.Expr); c != 0 {
		return c
	}
	if c := t.OrgTrack.CompareTo(tco.OrgTrack); c != 0 {
		return c
	}
	panic(&aterm.GomError{Msg: "Unable to compare"})
}

func (t *IsSortDeclDeclaration) CompareToLPO(o any) int {
	ao := o.(Declaration)
	if ao == Declaration(t) {
		return 0
	}
	if c := strings.Compare(t.SymbolName(), ao.SymbolName()); c != 0 {
		return c
	}
	tco := ao.(*IsSortDeclDeclaration)
	if c := t.TermArg.CompareToLPO(tco.TermArg); c != 0 {
		return c
	}
	if c := t.Expr.CompareToLPO(tco.Expr); c != 0 {
		return c
	}
	if c := t.OrgTrack.CompareToLPO(tco.OrgTrack); c != 0 {
		return c
	}
	panic(&aterm.GomError{Msg: "Unable to compare"})
}

// ToATerm is the ATerm of the term: an application of IsSortDecl.
func (t *IsSortDeclDeclaration) ToATerm() aterm.ATerm {
	f := aterm.GetInstance()
	return f.MakeAppl(f.MakeAFun("IsSortDecl", 3, false), t.TermArg.ToATerm(), t.Expr.ToATerm(), t.OrgTrack.ToATerm())
}

// fromTermIsSortDeclDeclaration is Java Gom's IsSortDecl.fromTerm: an unquoted application of
// IsSortDecl whose arguments are convertible (as in Java, the arity is not
// checked: a missing argument is an index out of range).
func fromTermIsSortDeclDeclaration(trm aterm.ATerm, conv aterm.ATermConverter) (Declaration, bool) {
	trm = conv.Convert(trm)
	if appl, ok := trm.(*aterm.ATermAppl); ok && appl.GetName() == "IsSortDecl" && !appl.GetAFun().IsQuoted() {
		return MakeIsSortDecl(BQTermFromTermConv(appl.GetArgument(0), conv), ExpressionFromTermConv(appl.GetArgument(1), conv), OptionFromTermConv(appl.GetArgument(2), conv)), true
	}
	return nil, false
}

