func (t *IsEmptyDeclDeclaration) CompareTo(o any) int {
	ao := o.(Declaration)
	if ao == Declaration(t) {
		return 0
	}
	if t.Hash() != ao.Hash() {
		if t.Hash() < ao.Hash() {
			return -1
		}
		return 1
	}
	if c := strings.Compare(t.SymbolName(), ao.SymbolName()); c != 0 {
		return c
	}
	tco := ao.(*IsEmptyDeclDeclaration)
	if c := t.Opname.CompareTo(tco.Opname); c != 0 {
		return c
	}
	if c := t.Variable.CompareTo(tco.Variable); c != 0 {
		return c
	}
	if c := t.Expr.CompareTo(tco.Expr); c != 0 {
		return c
	}
	if c := t.OrgTrack.CompareTo(tco.OrgTrack); c != 0 {
		return c
	}
	panic(&aterm.GomError{Msg: "Unable to compare"})
}

func (t *IsEmptyDeclDeclaration) CompareToLPO(o any) int {
	ao := o.(Declaration)
	if ao == Declaration(t) {
		return 0
	}
	if c := strings.Compare(t.SymbolName(), ao.SymbolName()); c != 0 {
		return c
	}
	tco := ao.(*IsEmptyDeclDeclaration)
	if c := t.Opname.CompareToLPO(tco.Opname); c != 0 {
		return c
	}
	if c := t.Variable.CompareToLPO(tco.Variable); c != 0 {
		return c
	}
	if c := t.Expr.CompareToLPO(tco.Expr); c != 0 {
		return c
	}
	if c := t.OrgTrack.CompareToLPO(tco.OrgTrack); c != 0 {
		return c
	}
	panic(&aterm.GomError{Msg: "Unable to compare"})
}

// ToATerm is the ATerm of the term: an application of IsEmptyDecl.
func (t *IsEmptyDeclDeclaration) ToATerm() aterm.ATerm {
	f := aterm.GetInstance()
	return f.MakeAppl(f.MakeAFun("IsEmptyDecl", 4, false), t.Opname.ToATerm(), t.Variable.ToATerm(), t.Expr.ToATerm(), t.OrgTrack.ToATerm())
}

// fromTermIsEmptyDeclDeclaration is Java Gom's IsEmptyDecl.fromTerm: an unquoted application of
// IsEmptyDecl whose arguments are convertible (as in Java, the arity is not
// checked: a missing argument is an index out of range).
func fromTermIsEmptyDeclDeclaration(trm aterm.ATerm, conv aterm.ATermConverter) (Declaration, bool) {
	trm = conv.Convert(trm)
	if appl, ok := trm.(*aterm.ATermAppl); ok && appl.GetName() == "IsEmptyDecl" && !appl.GetAFun().IsQuoted() {
		return MakeIsEmptyDecl(TomNameFromTermConv(appl.GetArgument(0), conv), BQTermFromTermConv(appl.GetArgument(1), conv), ExpressionFromTermConv(appl.GetArgument(2), conv), OptionFromTermConv(appl.GetArgument(3), conv)), true
	}
	return nil, false
}

