func (t *StrategyDeclaration) CompareTo(o any) int {
	ao := o.(Declaration)
	if ao == Declaration(t) {
		return 0
	}
	if t.Hash() != ao.Hash() {
		if t.Hash() < ao.Hash() {
			return -1
		}
		return 1
	}
	if c := strings.Compare(t.SymbolName(), ao.SymbolName()); c != 0 {
		return c
	}
	tco := ao.(*StrategyDeclaration)
	if c := t.SName.CompareTo(tco.SName); c != 0 {
		return c
	}
	if c := t.ExtendsTerm.CompareTo(tco.ExtendsTerm); c != 0 {
		return c
	}
	if c := t.VisitList.CompareTo(tco.VisitList); c != 0 {
		return c
	}
	if c := t.Hooks.CompareTo(tco.Hooks); c != 0 {
		return c
	}
	if c := t.OrgTrack.CompareTo(tco.OrgTrack); c != 0 {
		return c
	}
	panic(&aterm.GomError{Msg: "Unable to compare"})
}

func (t *StrategyDeclaration) CompareToLPO(o any) int {
	ao := o.(Declaration)
	if ao == Declaration(t) {
		return 0
	}
	if c := strings.Compare(t.SymbolName(), ao.SymbolName()); c != 0 {
		return c
	}
	tco := ao.(*StrategyDeclaration)
	if c := t.SName.CompareToLPO(tco.SName); c != 0 {
		return c
	}
	if c := t.ExtendsTerm.CompareToLPO(tco.ExtendsTerm); c != 0 {
		return c
	}
	if c := t.VisitList.CompareToLPO(tco.VisitList); c != 0 {
		return c
	}
	if c := t.Hooks.CompareToLPO(tco.Hooks); c != 0 {
		return c
	}
	if c := t.OrgTrack.CompareToLPO(tco.OrgTrack); c != 0 {
		return c
	}
	panic(&aterm.GomError{Msg: "Unable to compare"})
}

// ToATerm is the ATerm of the term: an application of Strategy.
func (t *StrategyDeclaration) ToATerm() aterm.ATerm {
	f := aterm.GetInstance()
	return f.MakeAppl(f.MakeAFun("Strategy", 5, false), t.SName.ToATerm(), t.ExtendsTerm.ToATerm(), t.VisitList.ToATerm(), t.Hooks.ToATerm(), t.OrgTrack.ToATerm())
}

// fromTermStrategyDeclaration is Java Gom's Strategy.fromTerm: an unquoted application of
// Strategy whose arguments are convertible (as in Java, the arity is not
// checked: a missing argument is an index out of range).
func fromTermStrategyDeclaration(trm aterm.ATerm, conv aterm.ATermConverter) (Declaration, bool) {
	trm = conv.Convert(trm)
	if appl, ok := trm.(*aterm.ATermAppl); ok && appl.GetName() == "Strategy" && !appl.GetAFun().IsQuoted() {
		return MakeStrategy(TomNameFromTermConv(appl.GetArgument(0), conv), BQTermFromTermConv(appl.GetArgument(1), conv), TomVisitListFromTermConv(appl.GetArgument(2), conv), DeclarationListFromTermConv(appl.GetArgument(3), conv), OptionFromTermConv(appl.GetArgument(4), conv)), true
	}
	return nil, false
}

// TransformationDeclaration is the term type for the alternative `Transformation(...)` of sort Declaration.
type TransformationDeclaration struct {
	TName           TomName
	Domain          TomTypeList
	ElementaryTList ElementaryTransformationList
	FileFrom        string
	FileTo          string
	OrgTrack        Option
	hash            uint32
}

func (*TransformationDeclaration) isDeclaration() {}

func (t *TransformationDeclaration) Hash() uint32 { return t.hash }

func (t *TransformationDeclaration) Equivalent(other sharedobjects.Term) bool {
	o, ok := other.(*TransformationDeclaration)
	if !ok {
		return false
	}
	if t.TName != o.TName {
		return false
	}
	if t.Domain != o.Domain {
		return false
	}
	if t.ElementaryTList != o.ElementaryTList {
		return false
	}
	if t.FileFrom != o.FileFrom {
		return false
	}
	if t.FileTo != o.FileTo {
		return false
	}
	if t.OrgTrack != o.OrgTrack {
		return false
	}
	return true
}

func (t *TransformationDeclaration) Duplicate() sharedobjects.Term {
	clone := *t
	return &clone
}

func (t *TransformationDeclaration) String() string {
	return "Transformation(" + fmt.Sprint(t.TName) + "," + fmt.Sprint(t.Domain) + "," + fmt.Sprint(t.ElementaryTList) + "," + sharedobjects.JavaEscape(t.FileFrom) + "," + sharedobjects.JavaEscape(t.FileTo) + "," + fmt.Sprint(t.OrgTrack) + ")"
}

func (t *TransformationDeclaration) ChildCount() int { return 6 }

func (t *TransformationDeclaration) ChildAt(i int) any {
	switch i {
	case 0:
		return t.TName
	case 1:
		return t.Domain
	case 2:
		return t.ElementaryTList
	case 3:
		return t.FileFrom
	case 4:
		return t.FileTo
	case 5:
		return t.OrgTrack
	}
	panic(fmt.Sprintf("TransformationDeclaration.ChildAt: index %d out of range", i))
}

func (t *TransformationDeclaration) SetChildAt(i int, child any) any {
	switch i {
	case 0:
		return MakeTransformation(child.(TomName), t.Domain, t.ElementaryTList, t.FileFrom, t.FileTo, t.OrgTrack)
	case 1:
		return MakeTransformation(t.TName, child.(TomTypeList), t.ElementaryTList, t.FileFrom, t.FileTo, t.OrgTrack)
	case 2:
		return MakeTransformation(t.TName, t.Domain, child.(ElementaryTransformationList), t.FileFrom, t.FileTo, t.OrgTrack)
	case 3:
		return MakeTransformation(t.TName, t.Domain, t.ElementaryTList, child.(string), t.FileTo, t.OrgTrack)
	case 4:
		return MakeTransformation(t.TName, t.Domain, t.ElementaryTList, t.FileFrom, child.(string), t.OrgTrack)
	case 5:
		return MakeTransformation(t.TName, t.Domain, t.ElementaryTList, t.FileFrom, t.FileTo, child.(Option))
	}
	panic(fmt.Sprintf("TransformationDeclaration.SetChildAt: index %d out of range", i))
}

func (t *TransformationDeclaration) Children() []any {
	return []any{t.TName, t.Domain, t.ElementaryTList, t.FileFrom, t.FileTo, t.OrgTrack}
}

func (t *TransformationDeclaration) SetChildren(children []any) any {
	return MakeTransformation(children[0].(TomName), children[1].(TomTypeList), children[2].(ElementaryTransformationList), children[3].(string), children[4].(string), children[5].(Option))
}

// MakeTransformation builds the canonical (shared) Transformation term.
func MakeTransformation(tName TomName, domain TomTypeList, elementaryTList ElementaryTransformationList, fileFrom string, fileTo string, orgTrack Option) Declaration {
	hashes := []uint32{tName.Hash(), domain.Hash(), elementaryTList.Hash(), sharedobjects.StringHash(fmt.Sprintf("%v", fileFrom)), sharedobjects.StringHash(fmt.Sprintf("%v", fileTo)), orgTrack.Hash()}
	proto := &TransformationDeclaration{hash: sharedobjects.MixSymbol(sharedobjects.StringHash("Transformation"), hashes), TName: tName, Domain: domain, ElementaryTList: elementaryTList, FileFrom: fileFrom, FileTo: fileTo, OrgTrack: orgTrack}
	return factory.Build(proto).(*TransformationDeclaration)
}

// IsTransformation is the `Is_Transformation` predicate strategy: succeeds (returns subject
// unchanged) when subject has the `Transformation` shape, otherwise fails with
// sl.ErrVisitFailure.
type IsTransformation struct{ sl.AbstractStrategy }

func (IsTransformation) VisitLight(subject any, _ sl.Introspector) (any, error) {
	if _, ok := subject.(*TransformationDeclaration); ok {
		return subject, nil
	}
	return subject, sl.ErrVisitFailure
}
func (IsTransformation) ChildCount() int             { return 0 }
func (IsTransformation) ChildAt(int) sl.Strategy     { panic("IsTransformation: no children") }
func (IsTransformation) SetChildAt(int, sl.Strategy) { panic("IsTransformation: no children") }
func (s *IsTransformation) VisitEnv(sl.Introspector) int {
	if _, ok := s.GetEnvironment().GetSubject().(*TransformationDeclaration); ok {
		return sl.StatusSuccess
	}
	return sl.StatusFailure
}
func (s *IsTransformation) Visit(subject any, intro sl.Introspector) (any, error) {
	return sl.VisitStrategy(s, subject, intro)
}
func (s *IsTransformation) VisitWith(env *sl.Environment, intro sl.Introspector) (any, error) {
	return sl.VisitStrategyWith(s, env, intro)
}

var _ sl.Strategy = (*IsTransformation)(nil)

// VisitTransformation is the `_Transformation` slot-visit strategy: when subject is `Transformation`,
// applies each constituent strategy to the matching child slot and
// rebuilds the term iff at least one child changed. Fails with
// sl.ErrVisitFailure when subject isn't `Transformation`.
type VisitTransformation struct {
	sl.AbstractStrategy
	args []sl.Strategy
}

// NewVisitTransformation builds the slot-visit strategy with the supplied per-slot
// sub-strategies.
func NewVisitTransformation(args ...sl.Strategy) *VisitTransformation {
	return &VisitTransformation{args: args}
}

func (s *VisitTransformation) VisitLight(subject any, intro sl.Introspector) (any, error) {
	if _, ok := subject.(*TransformationDeclaration); !ok {
		return subject, sl.ErrVisitFailure
	}
	if len(s.args) != 6 {
		return subject, sl.ErrVisitFailure
	}
	var newChildren []any
	for i := 0; i < 6; i++ {
		oldChild := intro.GetChildAt(subject, i)
		newChild, err := s.args[i].VisitLight(oldChild, intro)
		if err != nil {
			return subject, err
		}
		if newChildren != nil {
			newChildren[i] = newChild
		} else if newChild != oldChild {
			newChildren = intro.GetChildren(subject)
			newChildren[i] = newChild
		}
	}
	if newChildren != nil {
		return intro.SetChildren(subject, newChildren), nil
	}
	return subject, nil
}

func (s *VisitTransformation) ChildCount() int                 { return len(s.args) }
func (s *VisitTransformation) ChildAt(i int) sl.Strategy       { return s.args[i] }
func (s *VisitTransformation) SetChildAt(i int, v sl.Strategy) { s.args[i] = v }

func (s *VisitTransformation) VisitEnv(intro sl.Introspector) int {
	if _, ok := s.GetEnvironment().GetSubject().(*TransformationDeclaration); !ok {
		return sl.StatusFailure
	}
	if len(s.args) != 6 {
		return sl.StatusFailure
	}
	return sl.VisitCongruence(s.GetEnvironment(), intro, s.args, false)
}
func (s *VisitTransformation) Visit(subject any, intro sl.Introspector) (any, error) {
	return sl.VisitStrategy(s, subject, intro)
}
func (s *VisitTransformation) VisitWith(env *sl.Environment, intro sl.Introspector) (any, error) {
	return sl.VisitStrategyWith(s, env, intro)
}

var _ sl.Strategy = (*VisitTransformation)(nil)

