func (t *ResolveClassDeclDeclaration) CompareTo(o any) int {
	ao := o.(Declaration)
	if ao == Declaration(t) {
		return 0
	}
	if t.Hash() != ao.Hash() {
		if t.Hash() < ao.Hash() {
			return -1
		}
		return 1
	}
	if c := strings.Compare(t.SymbolName(), ao.SymbolName()); c != 0 {
		return c
	}
	tco := ao.(*ResolveClassDeclDeclaration)
	if c := t.AstName.CompareTo(tco.AstName); c != 0 {
		return c
	}
	if c := strings.Compare(t.WithName, tco.WithName); c != 0 {
		return c
	}
	if c := strings.Compare(t.ToName, tco.ToName); c != 0 {
		return c
	}
	if c := strings.Compare(t.Extends, tco.Extends); c != 0 {
		return c
	}
	panic(&aterm.GomError{Msg: "Unable to compare"})
}

