func (t *ReferenceClassDeclaration) CompareTo(o any) int {
	ao := o.(Declaration)
	if ao == Declaration(t) {
		return 0
	}
	if t.Hash() != ao.Hash() {
		if t.Hash() < ao.Hash() {
			return -1
		}
		return 1
	}
	if c := strings.Compare(t.SymbolName(), ao.SymbolName()); c != 0 {
		return c
	}
	tco := ao.(*ReferenceClassDeclaration)
	if c := t.RefName.CompareTo(tco.RefName); c != 0 {
		return c
	}
	if c := t.Fields.CompareTo(tco.Fields); c != 0 {
		return c
	}
	panic(&aterm.GomError{Msg: "Unable to compare"})
}

func (t *ReferenceClassDeclaration) CompareToLPO(o any) int {
	ao := o.(Declaration)
	if ao == Declaration(t) {
		return 0
	}
	if c := strings.Compare(t.SymbolName(), ao.SymbolName()); c != 0 {
		return c
	}
	tco := ao.(*ReferenceClassDeclaration)
	if c := t.RefName.CompareToLPO(tco.RefName); c != 0 {
		return c
	}
	if c := t.Fields.CompareToLPO(tco.Fields); c != 0 {
		return c
	}
	panic(&aterm.GomError{Msg: "Unable to compare"})
}

// ToATerm is the ATerm of the term: an application of ReferenceClass.
func (t *ReferenceClassDeclaration) ToATerm() aterm.ATerm {
	f := aterm.GetInstance()
	return f.MakeAppl(f.MakeAFun("ReferenceClass", 2, false), t.RefName.ToATerm(), t.Fields.ToATerm())
}

// fromTermReferenceClassDeclaration is Java Gom's ReferenceClass.fromTerm: an unquoted application of
// ReferenceClass whose arguments are convertible (as in Java, the arity is not
// checked: a missing argument is an index out of range).
func fromTermReferenceClassDeclaration(trm aterm.ATerm, conv aterm.ATermConverter) (Declaration, bool) {
	trm = conv.Convert(trm)
	if appl, ok := trm.(*aterm.ATermAppl); ok && appl.GetName() == "ReferenceClass" && !appl.GetAFun().IsQuoted() {
		return MakeReferenceClass(TomNameFromTermConv(appl.GetArgument(0), conv), RefClassTracelinkInstructionListFromTermConv(appl.GetArgument(1), conv)), true
	}
	return nil, false
}

// FunctionDefDeclaration is the term type for the alternative `FunctionDef(...)` of sort Declaration.
type FunctionDefDeclaration struct {
	AstName      TomName
	ArgumentList BQTermList
	Codomain     TomType
	ThrowsType   TomType
	Instruction  Instruction
	hash         uint32
}

func (*FunctionDefDeclaration) isDeclaration() {}

func (t *FunctionDefDeclaration) Hash() uint32 { return t.hash }

func (t *FunctionDefDeclaration) Equivalent(other sharedobjects.Term) bool {
	o, ok := other.(*FunctionDefDeclaration)
	if !ok {
		return false
	}
	if t.AstName != o.AstName {
		return false
	}
	if t.ArgumentList != o.ArgumentList {
		return false
	}
	if t.Codomain != o.Codomain {
		return false
	}
	if t.ThrowsType != o.ThrowsType {
		return false
	}
	if t.Instruction != o.Instruction {
		return false
	}
	return true
}

func (t *FunctionDefDeclaration) Duplicate() sharedobjects.Term {
	clone := *t
	return &clone
}

func (t *FunctionDefDeclaration) String() string {
	return "FunctionDef(" + fmt.Sprint(t.AstName) + "," + fmt.Sprint(t.ArgumentList) + "," + fmt.Sprint(t.Codomain) + "," + fmt.Sprint(t.ThrowsType) + "," + fmt.Sprint(t.Instruction) + ")"
}

func (t *FunctionDefDeclaration) ChildCount() int { return 5 }

func (t *FunctionDefDeclaration) ChildAt(i int) any {
	switch i {
	case 0:
		return t.AstName
	case 1:
		return t.ArgumentList
	case 2:
		return t.Codomain
	case 3:
		return t.ThrowsType
	case 4:
		return t.Instruction
	}
	panic(fmt.Sprintf("FunctionDefDeclaration.ChildAt: index %d out of range", i))
}

func (t *FunctionDefDeclaration) SetChildAt(i int, child any) any {
	switch i {
	case 0:
		return MakeFunctionDef(child.(TomName), t.ArgumentList, t.Codomain, t.ThrowsType, t.Instruction)
	case 1:
		return MakeFunctionDef(t.AstName, child.(BQTermList), t.Codomain, t.ThrowsType, t.Instruction)
	case 2:
		return MakeFunctionDef(t.AstName, t.ArgumentList, child.(TomType), t.ThrowsType, t.Instruction)
	case 3:
		return MakeFunctionDef(t.AstName, t.ArgumentList, t.Codomain, child.(TomType), t.Instruction)
	case 4:
		return MakeFunctionDef(t.AstName, t.ArgumentList, t.Codomain, t.ThrowsType, child.(Instruction))
	}
	panic(fmt.Sprintf("FunctionDefDeclaration.SetChildAt: index %d out of range", i))
}

func (t *FunctionDefDeclaration) Children() []any {
	return []any{t.AstName, t.ArgumentList, t.Codomain, t.ThrowsType, t.Instruction}
}

func (t *FunctionDefDeclaration) SetChildren(children []any) any {
	return MakeFunctionDef(children[0].(TomName), children[1].(BQTermList), children[2].(TomType), children[3].(TomType), children[4].(Instruction))
}

// MakeFunctionDef builds the canonical (shared) FunctionDef term.
func MakeFunctionDef(astName TomName, argumentList BQTermList, codomain TomType, throwsType TomType, instruction Instruction) Declaration {
	hashes := []uint32{astName.Hash(), argumentList.Hash(), codomain.Hash(), throwsType.Hash(), instruction.Hash()}
	proto := &FunctionDefDeclaration{hash: sharedobjects.MixSymbol(sharedobjects.StringHash("FunctionDef"), hashes), AstName: astName, ArgumentList: argumentList, Codomain: codomain, ThrowsType: throwsType, Instruction: instruction}
	return factory.Build(proto).(*FunctionDefDeclaration)
}

// IsFunctionDef is the `Is_FunctionDef` predicate strategy: succeeds (returns subject
// unchanged) when subject has the `FunctionDef` shape, otherwise fails with
// sl.ErrVisitFailure.
type IsFunctionDef struct{ sl.AbstractStrategy }

func (IsFunctionDef) VisitLight(subject any, _ sl.Introspector) (any, error) {
	if _, ok := subject.(*FunctionDefDeclaration); ok {
		return subject, nil
	}
	return subject, sl.ErrVisitFailure
}
func (IsFunctionDef) ChildCount() int             { return 0 }
func (IsFunctionDef) ChildAt(int) sl.Strategy     { panic("IsFunctionDef: no children") }
func (IsFunctionDef) SetChildAt(int, sl.Strategy) { panic("IsFunctionDef: no children") }
func (s *IsFunctionDef) VisitEnv(sl.Introspector) int {
	if _, ok := s.GetEnvironment().GetSubject().(*FunctionDefDeclaration); ok {
		return sl.StatusSuccess
	}
	return sl.StatusFailure
}
func (s *IsFunctionDef) Visit(subject any, intro sl.Introspector) (any, error) {
	return sl.VisitStrategy(s, subject, intro)
}
func (s *IsFunctionDef) VisitWith(env *sl.Environment, intro sl.Introspector) (any, error) {
	return sl.VisitStrategyWith(s, env, intro)
}

var _ sl.Strategy = (*IsFunctionDef)(nil)

// VisitFunctionDef is the `_FunctionDef` slot-visit strategy: when subject is `FunctionDef`,
// applies each constituent strategy to the matching child slot and
// rebuilds the term iff at least one child changed. Fails with
// sl.ErrVisitFailure when subject isn't `FunctionDef`.
type VisitFunctionDef struct {
	sl.AbstractStrategy
	args []sl.Strategy
}

// NewVisitFunctionDef builds the slot-visit strategy with the supplied per-slot
// sub-strategies.
func NewVisitFunctionDef(args ...sl.Strategy) *VisitFunctionDef {
	return &VisitFunctionDef{args: args}
}

func (s *VisitFunctionDef) VisitLight(subject any, intro sl.Introspector) (any, error) {
	if _, ok := subject.(*FunctionDefDeclaration); !ok {
		return subject, sl.ErrVisitFailure
	}
	if len(s.args) != 5 {
		return subject, sl.ErrVisitFailure
	}
	var newChildren []any
	for i := 0; i < 5; i++ {
		oldChild := intro.GetChildAt(subject, i)
		newChild, err := s.args[i].VisitLight(oldChild, intro)
		if err != nil {
			return subject, err
		}
		if newChildren != nil {
			newChildren[i] = newChild
		} else if newChild != oldChild {
			newChildren = intro.GetChildren(subject)
			newChildren[i] = newChild
		}
	}
	if newChildren != nil {
		return intro.SetChildren(subject, newChildren), nil
	}
	return subject, nil
}

func (s *VisitFunctionDef) ChildCount() int                 { return len(s.args) }
func (s *VisitFunctionDef) ChildAt(i int) sl.Strategy       { return s.args[i] }
func (s *VisitFunctionDef) SetChildAt(i int, v sl.Strategy) { s.args[i] = v }

func (s *VisitFunctionDef) VisitEnv(intro sl.Introspector) int {
	if _, ok := s.GetEnvironment().GetSubject().(*FunctionDefDeclaration); !ok {
		return sl.StatusFailure
	}
	if len(s.args) != 5 {
		return sl.StatusFailure
	}
	return sl.VisitCongruence(s.GetEnvironment(), intro, s.args, false)
}
func (s *VisitFunctionDef) Visit(subject any, intro sl.Introspector) (any, error) {
	return sl.VisitStrategy(s, subject, intro)
}
func (s *VisitFunctionDef) VisitWith(env *sl.Environment, intro sl.Introspector) (any, error) {
	return sl.VisitStrategyWith(s, env, intro)
}

var _ sl.Strategy = (*VisitFunctionDef)(nil)

