func (t *ClassDeclaration) CompareTo(o any) int {
	ao := o.(Declaration)
	if ao == Declaration(t) {
		return 0
	}
	if t.Hash() != ao.Hash() {
		if t.Hash() < ao.Hash() {
			return -1
		}
		return 1
	}
	if c := strings.Compare(t.SymbolName(), ao.SymbolName()); c != 0 {
		return c
	}
	tco := ao.(*ClassDeclaration)
	if c := t.AstName.CompareTo(tco.AstName); c != 0 {
		return c
	}
	if c := t.ExtendsType.CompareTo(tco.ExtendsType); c != 0 {
		return c
	}
	if c := t.SuperTerm.CompareTo(tco.SuperTerm); c != 0 {
		return c
	}
	if c := t.Declaration.CompareTo(tco.Declaration); c != 0 {
		return c
	}
	panic(&aterm.GomError{Msg: "Unable to compare"})
}

func (t *ClassDeclaration) CompareToLPO(o any) int {
	ao := o.(Declaration)
	if ao == Declaration(t) {
		return 0
	}
	if c := strings.Compare(t.SymbolName(), ao.SymbolName()); c != 0 {
		return c
	}
	tco := ao.(*ClassDeclaration)
	if c := t.AstName.CompareToLPO(tco.AstName); c != 0 {
		return c
	}
	if c := t.ExtendsType.CompareToLPO(tco.ExtendsType); c != 0 {
		return c
	}
	if c := t.SuperTerm.CompareToLPO(tco.SuperTerm); c != 0 {
		return c
	}
	if c := t.Declaration.CompareToLPO(tco.Declaration); c != 0 {
		return c
	}
	panic(&aterm.GomError{Msg: "Unable to compare"})
}

// ToATerm is the ATerm of the term: an application of Class.
func (t *ClassDeclaration) ToATerm() aterm.ATerm {
	f := aterm.GetInstance()
	return f.MakeAppl(f.MakeAFun("Class", 4, false), t.AstName.ToATerm(), t.ExtendsType.ToATerm(), t.SuperTerm.ToATerm(), t.Declaration.ToATerm())
}

// fromTermClassDeclaration is Java Gom's Class.fromTerm: an unquoted application of
// Class whose arguments are convertible (as in Java, the arity is not
// checked: a missing argument is an index out of range).
func fromTermClassDeclaration(trm aterm.ATerm, conv aterm.ATermConverter) (Declaration, bool) {
	trm = conv.Convert(trm)
	if appl, ok := trm.(*aterm.ATermAppl); ok && appl.GetName() == "Class" && !appl.GetAFun().IsQuoted() {
		return MakeClass(TomNameFromTermConv(appl.GetArgument(0), conv), TomTypeFromTermConv(appl.GetArgument(1), conv), BQTermFromTermConv(appl.GetArgument(2), conv), DeclarationFromTermConv(appl.GetArgument(3), conv)), true
	}
	return nil, false
}

