func (s *IsACSymbolDecl) VisitEnv(sl.Introspector) int {
	if _, ok := s.GetEnvironment().GetSubject().(*ACSymbolDeclDeclaration); ok {
		return sl.StatusSuccess
	}
	return sl.StatusFailure
}
