// DeclarationListFromTermConv is Java Gom's DeclarationList.fromTerm(trm, atConv): the term of
// the first operator of the sort that converts the ATerm; it panics
// (IllegalArgumentException) when there is none.
func DeclarationListFromTermConv(trm aterm.ATerm, conv aterm.ATermConverter) DeclarationList {
	converted := conv.Convert(trm)
	var results []DeclarationList
	if r, ok := fromTermConcDeclarationDeclarationList(converted, conv); ok {
		results = append(results, r)
	}
	if len(results) == 0 {
		panic(&aterm.GomError{Msg: fmt.Sprintf("%v is not a DeclarationList", trm), IllegalArgument: true})
	}
	return results[0]
}

