// ConcDeclarationDeclarationList is the term type of the variadic operator `concDeclaration(...)` of sort DeclarationList
// (Java's abstract class concDeclaration): a maximally-shared cons cell (Java's
// ConsconcDeclaration: a head and a tail) or the empty list (Java's EmptyconcDeclaration).
type ConcDeclarationDeclarationList struct {
	head  Declaration
	tail  DeclarationList
	empty bool
	hash  uint32
	// children caches the Visitable children (Java's children field)
	children atomic.Pointer[[]any]
}

func (*ConcDeclarationDeclarationList) isDeclarationList() {}

func (t *ConcDeclarationDeclarationList) Hash() uint32 { return t.hash }

func (t *ConcDeclarationDeclarationList) Equivalent(other sharedobjects.Term) bool {
	o, ok := other.(*ConcDeclarationDeclarationList)
	return ok && t.empty == o.empty && t.head == o.head && t.tail == o.tail
}

func (t *ConcDeclarationDeclarationList) Duplicate() sharedobjects.Term {
	return &ConcDeclarationDeclarationList{head: t.head, tail: t.tail, empty: t.empty, hash: t.hash}
}

// elements returns the cached Visitable children of the list: its
// elements (Java's getChildren, i.e. toArray).
// Java's getChildren is the typed toArray(new Declaration[]{}): a last tail
// that is not a list (of sort DeclarationList) cannot be stored in it
// (ArrayStoreException, a *aterm.GomError here).
func (t *ConcDeclarationDeclarationList) elements() []any {
	if c := t.children.Load(); c != nil {
		return *c
	}
	var cur DeclarationList = t
	for {
		c, ok := cur.(*ConcDeclarationDeclarationList)
		if !ok || c.empty {
			break
		}
		cur = c.tail
	}
	if c, ok := cur.(*ConcDeclarationDeclarationList); !ok || !c.empty {
		panic(&aterm.GomError{Msg: fmt.Sprintf("ArrayStoreException: the tail %v of a concDeclaration list is not a Declaration", cur)})
	}
	c := t.ToArray()
	t.children.Store(&c)
	return c
}

func (t *ConcDeclarationDeclarationList) ChildCount() int { return len(t.elements()) }

func (t *ConcDeclarationDeclarationList) ChildAt(i int) any { return t.elements()[i] }

func (t *ConcDeclarationDeclarationList) SetChildAt(i int, child any) any {
	dup := t.Children()
	dup[i] = child
	return t.SetChildren(dup)
}

func (t *ConcDeclarationDeclarationList) Children() []any { return append([]any(nil), t.elements()...) }

// SetChildren is Java's setChildren of a list: ConcDeclarationFromArray(children).
func (t *ConcDeclarationDeclarationList) SetChildren(children []any) any {
	args := make([]Declaration, len(children))
	for i, c := range children {
		args[i] = c.(Declaration)
	}
	return MakeConcDeclaration(args...)
}

func (t *ConcDeclarationDeclarationList) String() string {
	var b strings.Builder
	b.WriteString("concDeclaration(")
	var cur DeclarationList = t
	for {
		c, ok := cur.(*ConcDeclarationDeclarationList)
		if !ok {
			b.WriteString("," + fmt.Sprint(cur))
			break
		}
		if c.empty {
			break
		}
		if c != t {
			b.WriteString(",")
		}
		b.WriteString(fmt.Sprint(c.head))
		cur = c.tail
	}
	b.WriteString(")")
	return b.String()
}

