// without hook.
func realMakeEmptyConcDeclaration() DeclarationList {
	proto := &ConcDeclarationDeclarationList{empty: true, hash: sharedobjects.MixSymbol(sharedobjects.StringHash("EmptyconcDeclaration"), nil)}
	return factory.Build(proto).(*ConcDeclarationDeclarationList)
}

// RawConcDeclaration builds the concDeclaration list holding exactly args, without construction
// hook.
func RawConcDeclaration(args ...Declaration) DeclarationList {
	l := realMakeEmptyConcDeclaration()
	for i := len(args) - 1; i >= 0; i-- {
		l = RealMakeConsConcDeclaration(args[i], l)
	}
	return l
}

// EmptyConcDeclaration is Java Gom's EmptyconcDeclaration.make(): the empty concDeclaration list, after the
// construction hooks.
func EmptyConcDeclaration() DeclarationList {
	return realMakeEmptyConcDeclaration()
}

// ConsConcDeclaration is Java Gom's ConsconcDeclaration.make(head, tail): head inserted in front of
// tail, after the construction hooks (theory "" first).
func ConsConcDeclaration(head Declaration, tail DeclarationList) DeclarationList {
	return RealMakeConsConcDeclaration(head, tail)
}

// MakeConcDeclaration builds the list of args as Tom's `concDeclaration(args…)` does: from EmptyConcDeclaration,
// by ConsConcDeclaration, through the construction hooks (Java's concDeclaration.fromArray).
func MakeConcDeclaration(args ...Declaration) DeclarationList {
	var l DeclarationList = EmptyConcDeclaration()
	for i := len(args) - 1; i >= 0; i-- {
		l = ConsConcDeclaration(args[i], l)
	}
	return l
}

// ConcDeclarationFromArray is Java Gom's concDeclaration.fromArray(array).
func ConcDeclarationFromArray(array []Declaration) DeclarationList {
	return MakeConcDeclaration(array...)
}

// IsConcDeclaration is the `Is_concDeclaration` predicate strategy: succeeds (returns subject
// unchanged) when subject has the `concDeclaration` shape, otherwise fails with
// sl.ErrVisitFailure.
type IsConcDeclaration struct{ sl.AbstractStrategy }

func (IsConcDeclaration) VisitLight(subject any, _ sl.Introspector) (any, error) {
	if _, ok := subject.(*ConcDeclarationDeclarationList); ok {
		return subject, nil
	}
	return subject, sl.ErrVisitFailure
}
func (IsConcDeclaration) ChildCount() int             { return 0 }
func (IsConcDeclaration) ChildAt(int) sl.Strategy     { panic("IsConcDeclaration: no children") }
func (IsConcDeclaration) SetChildAt(int, sl.Strategy) { panic("IsConcDeclaration: no children") }
func (s *IsConcDeclaration) VisitEnv(sl.Introspector) int {
	if _, ok := s.GetEnvironment().GetSubject().(*ConcDeclarationDeclarationList); ok {
		return sl.StatusSuccess
	}
	return sl.StatusFailure
}
func (s *IsConcDeclaration) Visit(subject any, intro sl.Introspector) (any, error) {
	return sl.VisitStrategy(s, subject, intro)
}
func (s *IsConcDeclaration) VisitWith(env *sl.Environment, intro sl.Introspector) (any, error) {
	return sl.VisitStrategyWith(s, env, intro)
}

var _ sl.Strategy = (*IsConcDeclaration)(nil)

// VisitConcDeclaration is the `_concDeclaration` slot-visit strategy: when subject is `concDeclaration`,
// applies each constituent strategy to the matching child slot and
// rebuilds the term iff at least one child changed. Fails with
// sl.ErrVisitFailure when subject isn't `concDeclaration`.
type VisitConcDeclaration struct {
	sl.AbstractStrategy
	args []sl.Strategy
}

// NewVisitConcDeclaration builds the slot-visit strategy with the supplied per-slot
// sub-strategies.
func NewVisitConcDeclaration(args ...sl.Strategy) *VisitConcDeclaration {
	return &VisitConcDeclaration{args: args}
}

func (s *VisitConcDeclaration) VisitLight(subject any, intro sl.Introspector) (any, error) {
	if _, ok := subject.(*ConcDeclarationDeclarationList); !ok {
		return subject, sl.ErrVisitFailure
	}
	// Variadic alt: visit every element with args[0] (Java's
	// `_concX` invokes the sub-strategy on each list element).
	if len(s.args) == 0 {
		return subject, nil
	}
	count := intro.GetChildCount(subject)
	var newChildren []any
	for i := 0; i < count; i++ {
		oldChild := intro.GetChildAt(subject, i)
		newChild, err := s.args[0].VisitLight(oldChild, intro)
		if err != nil {
			return subject, err
		}
		if newChildren != nil {
			newChildren[i] = newChild
		} else if newChild != oldChild {
			newChildren = intro.GetChildren(subject)
			newChildren[i] = newChild
		}
	}
	if newChildren != nil {
		return intro.SetChildren(subject, newChildren), nil
	}
	return subject, nil
}

func (s *VisitConcDeclaration) ChildCount() int                 { return len(s.args) }
func (s *VisitConcDeclaration) ChildAt(i int) sl.Strategy       { return s.args[i] }
func (s *VisitConcDeclaration) SetChildAt(i int, v sl.Strategy) { s.args[i] = v }

func (s *VisitConcDeclaration) VisitEnv(intro sl.Introspector) int {
	if _, ok := s.GetEnvironment().GetSubject().(*ConcDeclarationDeclarationList); !ok {
		return sl.StatusFailure
	}
	return sl.VisitCongruence(s.GetEnvironment(), intro, s.args, true)
}
func (s *VisitConcDeclaration) Visit(subject any, intro sl.Introspector) (any, error) {
	return sl.VisitStrategy(s, subject, intro)
}
func (s *VisitConcDeclaration) VisitWith(env *sl.Environment, intro sl.Introspector) (any, error) {
	return sl.VisitStrategyWith(s, env, intro)
}

var _ sl.Strategy = (*VisitConcDeclaration)(nil)

// SymbolName is the symbol of the Java term: ConsconcDeclaration or EmptyconcDeclaration.
func (t *ConcDeclarationDeclarationList) SymbolName() string {
	if t.empty {
		return "EmptyconcDeclaration"
	}
	return "ConsconcDeclaration"
}

func (t *ConcDeclarationDeclarationList) IsConsconcDeclaration() bool  { return !t.empty }
func (t *ConcDeclarationDeclarationList) IsEmptyconcDeclaration() bool { return t.empty }

func (t *ConcDeclarationDeclarationList) GetHeadconcDeclaration() Declaration {
	if t.empty {
		panic(&aterm.GomError{Msg: "This DeclarationList has no HeadconcDeclaration"})
	}
	return t.head
}
func (t *ConcDeclarationDeclarationList) GetTailconcDeclaration() DeclarationList {
	if t.empty {
		panic(&aterm.GomError{Msg: "This DeclarationList has no TailconcDeclaration"})
	}
	return t.tail
}

// Length is Java's length(): the number of elements of the list (a
// tail that is not a concDeclaration list counts as one element).
func (t *ConcDeclarationDeclarationList) Length() int {
	res := 0
	var tl DeclarationList = t
	for {
		c, ok := tl.(*ConcDeclarationDeclarationList)
		if !ok || c.empty {
			return res
		}
		res++
		tl = c.tail
		if _, ok := tl.(*ConcDeclarationDeclarationList); !ok {
			res++
		}
	}
}

// ToArray returns the elements of the list (Java's Object[] toArray()),
// ending with its tail when that is not a concDeclaration list.
func (t *ConcDeclarationDeclarationList) ToArray() []any {
	out := make([]any, 0, t.Length())
	var cur DeclarationList = t
	for {
		c, ok := cur.(*ConcDeclarationDeclarationList)
		if !ok || c.empty {
			break
		}
		out = append(out, c.head)
		cur = c.tail
	}
	if c, ok := cur.(*ConcDeclarationDeclarationList); !ok || !c.empty {
		out = append(out, cur)
	}
	return out
}

// Reverse is Java's reverse(): the reversed list, built by ConsConcDeclaration
// (through the hooks).
func (t *ConcDeclarationDeclarationList) Reverse() DeclarationList {
	if t.empty {
		return t
	}
	var cur DeclarationList = t
	var rev DeclarationList = EmptyConcDeclaration()
	for {
		c, ok := cur.(*ConcDeclarationDeclarationList)
		if !ok || c.empty {
			break
		}
		rev = ConsConcDeclaration(c.head, rev)
		cur = c.tail
	}
	return rev
}

// Append is Java's append(element): the list with element added at its
// end, built by ConsConcDeclaration (through the hooks).
func (t *ConcDeclarationDeclarationList) Append(element Declaration) DeclarationList {
	var heads []Declaration
	var cur DeclarationList = t
	for {
		c, ok := cur.(*ConcDeclarationDeclarationList)
		if !ok || c.empty {
			break
		}
		heads = append(heads, c.head)
		cur = c.tail
	}
	var res DeclarationList
	if c, ok := cur.(*ConcDeclarationDeclarationList); ok && c.empty {
		res = ConsConcDeclaration(element, cur)
	} else {
		res = ConsConcDeclaration(element, cur)
	}
	for i := len(heads) - 1; i >= 0; i-- {
		res = ConsConcDeclaration(heads[i], res)
	}
	return res
}

func (t *ConcDeclarationDeclarationList) CompareTo(o any) int {
	for {
		ao := o.(DeclarationList)
		if ao == DeclarationList(t) {
			return 0
		}
		if t.Hash() != ao.Hash() {
			if t.Hash() < ao.Hash() {
				return -1
			}
			return 1
		}
		if c := strings.Compare(t.SymbolName(), ao.SymbolName()); c != 0 {
			return c
		}
		tco := ao.(*ConcDeclarationDeclarationList)
		if t.empty {
			panic(&aterm.GomError{Msg: "Unable to compare"})
		}
		if c := t.head.CompareTo(tco.head); c != 0 {
			return c
		}
		next, ok := t.tail.(*ConcDeclarationDeclarationList)
		if !ok {
			if c := t.tail.CompareTo(tco.tail); c != 0 {
				return c
			}
			panic(&aterm.GomError{Msg: "Unable to compare"})
		}
		t, o = next, tco.tail
	}
}

func (t *ConcDeclarationDeclarationList) CompareToLPO(o any) int {
	for {
		ao := o.(DeclarationList)
		if ao == DeclarationList(t) {
			return 0
		}
		if c := strings.Compare(t.SymbolName(), ao.SymbolName()); c != 0 {
			return c
		}
		tco := ao.(*ConcDeclarationDeclarationList)
		if t.empty {
			panic(&aterm.GomError{Msg: "Unable to compare"})
		}
		if c := t.head.CompareToLPO(tco.head); c != 0 {
			return c
		}
		next, ok := t.tail.(*ConcDeclarationDeclarationList)
		if !ok {
			if c := t.tail.CompareToLPO(tco.tail); c != 0 {
				return c
			}
			panic(&aterm.GomError{Msg: "Unable to compare"})
		}
		t, o = next, tco.tail
	}
}

// ToATerm is Java's toATerm: the list of the elements, ending with the
// ATerm list of the tail (a tail that is not a list is Java's
// ClassCastException).
func (t *ConcDeclarationDeclarationList) ToATerm() aterm.ATerm {
	f := aterm.GetInstance()
	var heads []Declaration
	var cur DeclarationList = t
	for {
		c, ok := cur.(*ConcDeclarationDeclarationList)
		if !ok || c.empty {
			break
		}
		heads = append(heads, c.head)
		cur = c.tail
	}
	l := f.MakeListEmpty()
	if c, ok := cur.(*ConcDeclarationDeclarationList); !ok || !c.empty {
		tl, isList := cur.ToATerm().(*aterm.ATermList)
		if !isList {
			panic(&aterm.GomError{Msg: fmt.Sprintf("ClassCastException: the ATerm of %v is not an ATermList", cur)})
		}
		l = tl
	}
	for i := len(heads) - 1; i >= 0; i-- {
		l = f.MakeList(heads[i].ToATerm(), l)
	}
	return l
}

// fromTermConcDeclarationDeclarationList is Java Gom's concDeclaration.fromTerm: an application of concDeclaration, or a
// list (of ToATerm), of convertible elements.
func fromTermConcDeclarationDeclarationList(trm aterm.ATerm, conv aterm.ATermConverter) (res DeclarationList, ok bool) {
	trm = conv.Convert(trm)
	if appl, isAppl := trm.(*aterm.ATermAppl); isAppl && appl.GetName() == "concDeclaration" {
		elems := make([]Declaration, appl.GetArity())
		for i, a := range appl.GetArguments() {
			elems[i] = DeclarationFromTermConv(a, conv)
		}
		return MakeConcDeclaration(elems...), true
	}
	if list, isList := trm.(*aterm.ATermList); isList {
		// an element that cannot be converted: not a concDeclaration (Java returns null)
		defer func() {
			if recover() != nil {
				res, ok = nil, false
			}
		}()
		var elems []Declaration
		for !list.IsEmpty() {
			elems = append(elems, DeclarationFromTermConv(list.GetFirst(), conv))
			list = list.GetNext()
		}
		return MakeConcDeclaration(elems...), true
	}
	return nil, false
}
